remarks.example:
Basic usage:

var client = new HighSpeedEServerClient();
client.Connect("192.168.1.100");
var status = client.GetStatusInformation();
var position = client.GetRobotCartesianPosition();
client.Close();

Basic usage:

var client = new EServerClient();
client.Connect("192.168.1.100");
var status = client.GetStatus();
var position = client.GetCartesianPosition();
client.Close();

remarks.para:
Example usage:

var parameters = new EServerConnectParameters
{
    Port = 80,
    TimeoutMilliseconds = 5000
};
client.Connect("192.168.1.100", parameters);

remarks.example:
Basic usage:

var client = new HttpClient();
client.Connect("192.168.1.100");
var jobs = client.GetFileList(FileExtension.JOB);
var content = client.GetFile("FG2.JBI");
client.Close();

member.example:
Basic usage with High Speed Ethernet Server:

var robot = new YaskawaRobot();
robot.Connect("192.168.1.1");
var status = robot.HighSpeedEServer.GetStatusInformation();
Console.WriteLine($"Robot is in {status.Mode} mode");
robot.Disconnect();
